style.css:
@-moz-document domain("google.com"), domain("www.google.com") {
/* Body background and font */
  body {
    background: linear-gradient(135deg, #fffaf0, #ffeef8) !important;
    font-family: 'Comic Sans MS', 'Chalkboard SE', cursive, sans-serif !important;
    color: #333 !important;
  }

  /* Replace the Google logo with a kawaii one */
  /* Note: Update the URL below with your desired kawaii logo image */
  #hplogo, .logo {
    background-image: url("https://your-kawaii-logo-url.png") !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    width: 300px !important;
    height: 100px !important;
    margin: 20px auto !important;
  }

  /* Styling the search input box */
  input[type="text"],
  input[type="search"] {
    background: #fff0f5 !important;
    border: 2px solid #ffb6c1 !important;
    border-radius: 25px !important;
    padding: 10px !important;
    box-shadow: 0 2px 5px rgba(255,182,193, 0.5) !important;
  }

  /* Styling the search button(s) */
  input[type="submit"],
  button {
    background: #ffb6c1 !important;
    border: none !important;
    border-radius: 25px !important;
    color: #fff !important;
    padding: 10px 20px !important;
    font-size: 16px !important;
    cursor: pointer !important;
    box-shadow: 0 2px 5px rgba(255,182,193, 0.5) !important;
    transition: background 0.3s ease !important;
  }

  input[type="submit"]:hover,
  button:hover {
    background: #ff8da8 !important;
  }

  /* Cute link colors */
  a {
    color: #ff6f91 !important;
    text-decoration: none;
  }

  a:hover {
    color: #ff3f71 !important;
    text-decoration: underline;
  }

  /* Optional: Style the footer (if present) */
  #fbar {
    background: rgba(255,228,225,0.6) !important;
    border-top: 1px solid #ffb6c1 !important;
  }
}
